css_shell:
/* ---------- ajustes de la página ampliada ---------- */
/* seis pestañas: algo menos de relleno para que quepan en una fila */
.tabs button{padding:12px 10px 10px}
/* pantalla estrecha: una columna 1fr no baja de su contenido mínimo y desbordaba; minmax(0,1fr) sí */
@media (max-width:960px){.part-st main,.part-bn main{grid-template-columns:minmax(0,1fr)}}
@media (max-width:820px){.part-ms .wrap{grid-template-columns:minmax(0,1fr)}}
.part-st .grid2,.part-bn .grid2{grid-template-columns:minmax(0,1fr)}
.part-st main>*,.part-bn main>*,.part-ms .wrap>*,.part-st .grid2>*,.part-bn .grid2>*{min-width:0}
.part-st select,.part-bn select{max-width:100%}
@media (max-width:560px){.part-ms .swTable{display:block;max-width:100%;overflow-x:auto}}
